import{r as e}from"./createLucideIcon-DE-lQ5q9.js";var t={async getDepartmentTree(){return(await e.get(`/departments/tree`)).data},async getAllDepartments(t){return(await e.get(`/departments`,{params:{...t,tree:`false`}})).data},async getDepartments(e){return this.getAllDepartments(e)},async getDepartmentById(t){return(await e.get(`/departments/${t}`)).data},async createDepartment(t){return(await e.post(`/departments`,t)).data},async updateDepartment(t,n){return(await e.put(`/departments/${t}`,n)).data},async deleteDepartment(t){await e.delete(`/departments/${t}`)}};export{t};